'use strict';
let nutritionTab='diet',nutritionPlanId='',nutritionEditorUntil=0;
const nutritionNumber=n=>Number(n||0).toLocaleString('pt-BR',{maximumFractionDigits:1});
function nutritionData(){return db.settings.nutrition||{plans:[],measurements:[]}}
function nutritionEditing(){return Date.now()<nutritionEditorUntil}
function lockNutrition(){nutritionEditorUntil=0}
function nutritionCurrent(){const data=nutritionData();return data.plans.find(p=>p.id===nutritionPlanId)||data.plans[0]}
function nutritionCommit(data){db.settings.nutrition=data;if(!save())return false;close();render();return true}
function nutritionRequire(action){if(nutritionEditing()){nutritionEditorUntil=Date.now()+15*60*1000;action();return}modal(`<div class="nutri-lock-icon">🔒</div><h2>Acesso de nutricionista</h2><p class="muted">Digite o PIN para cadastrar ou editar o planejamento e as medidas.</p><form id="nutritionpinform" class="form"><label>PIN de edição<input name="pin" type="password" inputmode="numeric" autocomplete="off" pattern="[0-9]{4}" minlength="4" maxlength="4" required placeholder="••••"></label><p id="nutritionpinerror" class="nutri-error" role="alert"></p><button type="submit" class="primary">Liberar edição</button></form>`);$('#nutritionpinform').onsubmit=e=>{e.preventDefault();const input=e.target.elements.pin;if(input.value!=='0000'){input.value='';$('#nutritionpinerror').textContent='PIN incorreto. Tente novamente.';input.focus();return}input.value='';nutritionEditorUntil=Date.now()+15*60*1000;close();render();action()};$('#nutritionpinform input').focus()}
function nutrition(){const data=nutritionData(),plan=nutritionCurrent(),editor=nutritionEditing(),meals=plan?[...plan.meals].sort((a,b)=>a.time.localeCompare(b.time)):[],totals=meals.reduce((a,m)=>({kcal:a.kcal+m.kcal,protein:a.protein+m.protein,carbs:a.carbs+m.carbs,fat:a.fat+m.fat}),{kcal:0,protein:0,carbs:0,fat:0});return `<div class="nutrition-page">${heading('Nutrição <span class="nutri-title-emoji">🥑</span>','Seu planejamento, refeição por refeição.',`<button id="nutritionaccess" class="nutri-access">${editor?'🔓 Encerrar edição':'🔒 Nutricionista'}</button>`)}<div class="nutri-tabs" role="tablist" aria-label="Seções de nutrição"><button role="tab" aria-selected="${nutritionTab==='diet'}" data-nutritab="diet">🍽️ Alimentação</button><button role="tab" aria-selected="${nutritionTab==='body'}" data-nutritab="body">📏 Antropometria</button></div>${editor?'<div class="nutri-editor-note" role="status">Edição liberada · bloqueia ao sair da aba ou após 15 minutos.</div>':''}${nutritionTab==='body'?nutritionAnthropometry(data,editor):`<section class="nutri-plan-picker"><div><span class="nutri-eyebrow">PLANEJAMENTO ALIMENTAR</span>${data.plans.length?`<label class="sr-nutri" for="nutritionplan">Escolher planejamento alimentar</label><select id="nutritionplan">${data.plans.map(p=>`<option value="${esc(p.id)}" ${p.id===plan.id?'selected':''}>${esc(p.emoji+' '+p.name)}</option>`).join('')}</select>`:'<h2>Sua alimentação começa aqui</h2>'}</div><button id="nutritionnewplan" class="nutri-add" aria-label="Novo planejamento alimentar">＋</button></section>${plan?`<div class="nutri-summary" aria-label="Metas diárias do planejamento"><div><span>🔥 Energia</span><strong>${nutritionNumber(totals.kcal)}<small> kcal</small></strong><em>por dia</em></div><div><span>💪 Proteína</span><strong>${nutritionNumber(totals.protein)}<small> g</small></strong><em>por dia</em></div><div><span>💧 Água</span><strong>${nutritionNumber(plan.waterMl/1000)}<small> L</small></strong><em>por dia</em></div></div><div class="nutri-plan-meta"><p>${esc(plan.description||'Organizado para a sua rotina.')}</p>${editor?`<button id="nutritioneditplan" class="ghost">${icon('pencil')} Editar plano</button>`:''}</div><div class="nutri-section-title"><h2>Suas refeições <span>${meals.length}</span></h2><button id="nutritionnewmeal" class="ghost">＋ Refeição</button></div><div class="nutri-meals">${meals.map(m=>`<article class="nutri-meal"><div class="nutri-meal-heading"><span class="nutri-meal-emoji">${esc(m.emoji)}</span><div><h3>${esc(m.name)}</h3><span class="nutri-time">${esc(m.time)}</span></div>${editor?`<button class="nutri-icon-button" data-nutrimeal="${esc(m.id)}" aria-label="Editar ${esc(m.name)}">${icon('pencil')}</button>`:''}</div><ul class="nutri-foods">${m.foods.map(food=>`<li><span class="nutri-food-dot"></span>${esc(food)}</li>`).join('')}</ul>${m.note?`<p class="nutri-meal-note">${esc(m.note)}</p>`:''}<footer class="nutri-macros"><span><b>${nutritionNumber(m.kcal)}</b> kcal</span><span><b>${nutritionNumber(m.protein)} g</b> proteína</span><span><b>${nutritionNumber(m.carbs)} g</b> carboidratos</span><span><b>${nutritionNumber(m.fat)} g</b> lipídios</span></footer></article>`).join('')||'<div class="nutri-empty">🍽️<h3>As refeições ainda não foram cadastradas</h3><p>O nutricionista pode incluir os alimentos, horários e valores de cada refeição.</p></div>'}</div><p class="nutri-footnote">Valores cadastrados pelo nutricionista. Os totais somam as refeições deste planejamento.</p>`:`<div class="nutri-empty">🥑<h3>Um espaço para cuidar da sua rotina</h3><p>Cadastre um planejamento com refeições, horários e a quantidade diária de água.</p><button id="nutritionfirstplan" class="primary">Criar planejamento</button></div>`}`}</div>`}
function nutritionAnthropometry(data,editor){const rows=[...data.measurements].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)),last=rows[0];return `<div class="nutri-section-title"><div><span class="nutri-eyebrow">ACOMPANHAMENTO</span><h2>Antropometria</h2></div><button id="nutritionnewmeasure" class="primary">＋ Avaliação</button></div>${last?`<p class="muted">Última avaliação · ${fmt(last.date)}</p><div class="nutri-summary nutri-body-summary"><div><span>⚖️ Peso</span><strong>${nutritionNumber(last.weight)}<small> kg</small></strong></div><div><span>📏 Altura</span><strong>${nutritionNumber(last.height)}<small> cm</small></strong></div><div><span>◌ Gordura</span><strong>${nutritionNumber(last.bodyFat)}<small> %</small></strong></div></div><h2 class="section-gap">Histórico de avaliações</h2><div class="nutri-measures">${rows.map(r=>`<article class="nutri-measure"><div class="row between"><h3>${parse(r.date).toLocaleDateString('pt-BR')}</h3>${editor?`<button class="nutri-icon-button" data-nutrimeasure="${esc(r.id)}" aria-label="Editar avaliação de ${esc(r.date)}">${icon('pencil')}</button>`:''}</div><div class="nutri-measure-values"><span><b>${nutritionNumber(r.weight)} kg</b>Peso</span><span><b>${nutritionNumber(r.height)} cm</b>Altura</span><span><b>${nutritionNumber(r.bodyFat)}%</b>Gordura</span></div>${r.note?`<p>${esc(r.note)}</p>`:''}</article>`).join('')}</div>`:'<div class="nutri-empty">📏<h3>Seu acompanhamento fica aqui</h3><p>O nutricionista pode cadastrar peso, altura e percentual de gordura por avaliação.</p></div>'}`}
function nutritionDecimal(value,min=0,max=100000){const normalized=String(value).trim().replace(',','.');if(!/^(?:\d+(?:\.\d+)?|\.\d+)$/.test(normalized))throw Error('Preencha os valores numéricos corretamente.');const n=Number(normalized);if(!Number.isFinite(n)||n<min||n>max)throw Error('Um dos valores está fora do intervalo permitido.');return n}
function nutritionInput(name,label,value,placeholder='0'){return `<label>${label}<input name="${name}" inputmode="decimal" type="text" value="${esc(value??'')}" placeholder="${placeholder}" required></label>`}
function nutritionFormError(e){$('#nutritionformerror').textContent=e.message}
function nutritionFormFooter(label,id){return `<p id="nutritionformerror" class="nutri-error" role="alert"></p><div class="nutri-form-actions">${id?'<button type="button" id="nutritiondelete" class="nutri-danger">'+icon('trash')+' Excluir</button>':''}<button type="button" id="nutritioncancel">Cancelar</button><button class="primary" type="submit">${label}</button></div>`}
function nutritionDelete(kind,id,planId){if(!nutritionEditing()){nutritionRequire(()=>nutritionDelete(kind,id,planId));return}modal(`<div class="nutri-lock-icon">🗑️</div><h2>Excluir ${kind==='plan'?'planejamento':kind==='meal'?'refeição':'avaliação'}?</h2><p>${kind==='plan'?'As refeições deste planejamento também serão excluídas.':'Este registro será removido.'}</p><div class="modal-actions"><button id="nutritioncanceldelete">Cancelar</button><button id="nutritionconfirmdelete" class="nutri-danger">Excluir</button></div>`);$('#nutritioncanceldelete').onclick=()=>{close();if(kind==='plan')nutritionPlanForm(id);else if(kind==='meal')nutritionMealForm(id,planId);else nutritionMeasureForm(id)};$('#nutritionconfirmdelete').onclick=()=>{if(!nutritionEditing()){close();nutritionRequire(()=>nutritionDelete(kind,id,planId));return}const data=structuredClone(nutritionData());if(kind==='plan'){data.plans=data.plans.filter(p=>p.id!==id);nutritionPlanId=data.plans[0]?.id||''}else if(kind==='meal'){const p=data.plans.find(p=>p.id===planId);if(p)p.meals=p.meals.filter(m=>m.id!==id)}else data.measurements=data.measurements.filter(r=>r.id!==id);nutritionCommit(data)}}
function nutritionPlanForm(id){if(!nutritionEditing()){nutritionRequire(()=>nutritionPlanForm(id));return}const p=nutritionData().plans.find(p=>p.id===id);modal(`<h2>${p?'Editar':'Novo'} planejamento</h2><form id="nutritionplanform" class="form nutri-form"><label>Nome do planejamento<input name="name" required maxlength="100" value="${esc(p?.name||'')}" placeholder="Ex.: Rotina da semana"></label><label>Ícone<select name="emoji">${['🥑','🍽️','🌿','💪','☀️','🌷','🏃'].map(em=>`<option ${p?.emoji===em?'selected':''}>${em}</option>`).join('')}</select></label>${nutritionInput('water','Água por dia · litros',p?nutritionNumber(p.waterMl/1000):'','2,0')}<label>Orientações · opcional<textarea name="description" maxlength="2000" placeholder="Observações sobre este planejamento">${esc(p?.description||'')}</textarea></label>${nutritionFormFooter('Salvar planejamento',id)}</form>`);$('#nutritioncancel').onclick=close;if(id)$('#nutritiondelete').onclick=()=>nutritionDelete('plan',id);$('#nutritionplanform').onsubmit=e=>{e.preventDefault();if(!nutritionEditing()){close();nutritionRequire(()=>nutritionPlanForm(id));return}try{const f=new FormData(e.target),name=f.get('name').trim();if(!name)throw Error('Informe o nome do planejamento.');const data=structuredClone(nutritionData()),current=data.plans.find(x=>x.id===id);if(id&&!current)throw Error('Este planejamento foi removido em outro aparelho.');const entry={...current,id:id||uid(),name,emoji:f.get('emoji'),waterMl:Math.round(nutritionDecimal(f.get('water'),0,20)*1000),description:f.get('description').trim(),meals:current?.meals||[]};if(current)Object.assign(current,entry);else data.plans.push(entry);nutritionPlanId=entry.id;nutritionCommit(data)}catch(error){nutritionFormError(error)}}}
function nutritionMealForm(id,planId=nutritionCurrent()?.id){if(!nutritionEditing()){nutritionRequire(()=>nutritionMealForm(id,planId));return}const p=nutritionData().plans.find(x=>x.id===planId);if(!p){toast('Crie um planejamento primeiro.');return}const m=p.meals.find(x=>x.id===id);modal(`<h2>${m?'Editar':'Nova'} refeição</h2><p class="muted">${esc(p.name)}</p><form id="nutritionmealform" class="form nutri-form"><label>Nome da refeição<input name="name" required maxlength="100" value="${esc(m?.name||'')}" placeholder="Ex.: Café da manhã"></label><div class="pair"><label>Horário<input name="time" type="time" required value="${esc(m?.time||'08:00')}"></label><label>Ícone<select name="emoji">${['🍳','🥗','🍽️','🍎','🥪','☕','🥣','🌙'].map(em=>`<option ${m?.emoji===em?'selected':''}>${em}</option>`).join('')}</select></label></div><label>Alimentos e quantidades<textarea name="foods" class="nutri-food-editor" required maxlength="8000" placeholder="3 un — ovos&#10;2 fatias — pão de forma&#10;50 ml — café">${esc(m?.foods.join('\n')||'')}</textarea><small>Um alimento por linha, incluindo sua quantidade.</small></label><h3>Valores da refeição</h3><small>Preenchidos manualmente; os alimentos não calculam os valores.</small><div class="pair">${nutritionInput('kcal','Energia · kcal',m?.kcal)}${nutritionInput('protein','Proteína · g',m?.protein)}</div><div class="pair">${nutritionInput('carbs','Carboidratos · g',m?.carbs)}${nutritionInput('fat','Lipídios · g',m?.fat)}</div><label>Observação · opcional<textarea name="note" maxlength="2000">${esc(m?.note||'')}</textarea></label>${nutritionFormFooter('Salvar refeição',id)}</form>`);$('#nutritioncancel').onclick=close;if(id)$('#nutritiondelete').onclick=()=>nutritionDelete('meal',id,planId);$('#nutritionmealform').onsubmit=e=>{e.preventDefault();if(!nutritionEditing()){close();nutritionRequire(()=>nutritionMealForm(id,planId));return}try{const f=new FormData(e.target),name=f.get('name').trim(),foods=f.get('foods').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!name||!foods.length)throw Error('Informe o nome e pelo menos um alimento.');if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(f.get('time')))throw Error('Informe um horário válido.');const data=structuredClone(nutritionData()),parent=data.plans.find(x=>x.id===planId),current=parent?.meals.find(x=>x.id===id);if(!parent||id&&!current)throw Error('Esta refeição ou seu planejamento foi removido em outro aparelho.');const entry={id:id||uid(),name,emoji:f.get('emoji'),time:f.get('time'),foods,kcal:nutritionDecimal(f.get('kcal')),protein:nutritionDecimal(f.get('protein')),carbs:nutritionDecimal(f.get('carbs')),fat:nutritionDecimal(f.get('fat')),note:f.get('note').trim()};if(current)Object.assign(current,entry);else parent.meals.push(entry);nutritionCommit(data)}catch(error){nutritionFormError(error)}}}
function nutritionMeasureForm(id){if(!nutritionEditing()){nutritionRequire(()=>nutritionMeasureForm(id));return}const r=nutritionData().measurements.find(x=>x.id===id);modal(`<h2>${r?'Editar avaliação':'Nova avaliação'}</h2><form id="nutritionmeasureform" class="form nutri-form"><label>Data da avaliação<input name="date" type="date" required value="${esc(r?.date||iso(today))}"></label><div class="pair">${nutritionInput('weight','Peso · kg',r?.weight,'60,0')}${nutritionInput('height','Altura · cm',r?.height,'165')}</div>${nutritionInput('bodyFat','Gordura corporal · %',r?.bodyFat,'25,0')}<label>Observações · opcional<textarea name="note" maxlength="2000">${esc(r?.note||'')}</textarea></label>${nutritionFormFooter('Salvar avaliação',id)}</form>`);$('#nutritioncancel').onclick=close;if(id)$('#nutritiondelete').onclick=()=>nutritionDelete('measure',id);$('#nutritionmeasureform').onsubmit=e=>{e.preventDefault();if(!nutritionEditing()){close();nutritionRequire(()=>nutritionMeasureForm(id));return}try{const f=new FormData(e.target),date=f.get('date');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(+parse(date))||iso(parse(date))!==date)throw Error('Informe uma data válida.');const data=structuredClone(nutritionData()),current=data.measurements.find(x=>x.id===id);if(id&&!current)throw Error('Esta avaliação foi removida em outro aparelho.');const entry={id:id||uid(),createdAt:current?.createdAt||new Date().toISOString(),date,weight:nutritionDecimal(f.get('weight'),.1,1000),height:nutritionDecimal(f.get('height'),1,300),bodyFat:nutritionDecimal(f.get('bodyFat'),0,100),note:f.get('note').trim()};if(current)Object.assign(current,entry);else data.measurements.push(entry);nutritionTab='body';nutritionCommit(data)}catch(error){nutritionFormError(error)}}}
function bindNutrition(){const on=(s,fn)=>{const el=$(s);if(el)el.onclick=fn};on('#nutritionaccess',()=>{if(nutritionEditing()){lockNutrition();render()}else nutritionRequire(()=>render())});document.querySelectorAll('[data-nutritab]').forEach(b=>b.onclick=()=>{nutritionTab=b.dataset.nutritab;render()});const select=$('#nutritionplan');if(select)select.onchange=e=>{nutritionPlanId=e.target.value;render()};on('#nutritionnewplan',()=>nutritionPlanForm());on('#nutritionfirstplan',()=>nutritionPlanForm());on('#nutritioneditplan',()=>nutritionPlanForm(nutritionCurrent()?.id));on('#nutritionnewmeal',()=>nutritionMealForm());on('#nutritionnewmeasure',()=>nutritionMeasureForm());document.querySelectorAll('[data-nutrimeal]').forEach(b=>b.onclick=()=>nutritionMealForm(b.dataset.nutrimeal));document.querySelectorAll('[data-nutrimeasure]').forEach(b=>b.onclick=()=>nutritionMeasureForm(b.dataset.nutrimeasure))}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){lockNutrition();if(page==='nutrition'&&!$('#modal').open)render()}});
